<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import type { Component } from 'vue'
import { Calendar, Check, CircleCheck, CopyDocument, Delete, Document, EditPen, Grid, InfoFilled, List, Paperclip, Plus, Rank, Refresh, Setting, Tickets, Upload, User, View } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import UiPageHeader from '../components/ui/UiPageHeader.vue'
import { apiErrorMessage } from '../api/error'
import { createFormMetadataView, createFormMetadataViewField, deleteFormMetadataViewField, getFormMetadataSchema, getFormMetadataView, listFormMetadataScopes, listFormMetadataViews, publishFormMetadataView, updateFormMetadataView, updateFormMetadataViewField } from '../api/form-metadata'
import type { FormMetadataField, FormMetadataFormMode, FormMetadataScope, FormMetadataView, FormMetadataViewField, FormMetadataViewRole, FormMetadataViewSchema, FormMetadataViewType } from '../types/form-metadata'

type ViewMode = 'design' | 'preview' | 'schema'
type ViewSection = { key: string; title: string; layoutMode: 'left' | 'right' | 'full'; showTitle: boolean; collapsed: boolean; sortNo: number }
type ViewLayout = { columns: number; mobileColumns: number; labelPosition: string; mobileMode?: string; sections: ViewSection[] }

const scopes = ref<FormMetadataScope[]>([])
const selectedScopeId = ref<number | null>(null)
const scopeSchema = ref<{ fields: FormMetadataField[] } | null>(null)
const views = ref<FormMetadataView[]>([])
const selectedViewId = ref<number | null>(null)
const viewSchema = ref<FormMetadataViewSchema | null>(null)
const viewMode = ref<ViewMode>('design')
const loading = ref(false)
const saving = ref(false)
const pageError = ref('')
const selectedFieldId = ref<number | null>(null)
const draggingFieldId = ref<number | null>(null)
const dragOverIndex = ref<number | null>(null)
const dragOverSectionKey = ref<string | null>(null)
const localFields = ref<FormMetadataViewField[]>([])
const localLayout = ref<ViewLayout>(createDefaultLayout())
const activeSectionKey = ref('default')
const previewForm = ref<Record<string, unknown>>({})

const pageRoles: Array<{ key: FormMetadataViewRole; label: string; description: string; icon: Component }> = [
  { key: 'list', label: '列表页', description: '业务入口与检索', icon: List },
  { key: 'detail', label: '详情页', description: '只读信息展示', icon: Tickets },
  { key: 'create', label: '新建页', description: '创建业务对象', icon: Plus },
  { key: 'edit', label: '编辑页', description: '维护业务对象', icon: EditPen },
  { key: 'approval', label: '审批页', description: '审批上下文展示', icon: CircleCheck }
]
const viewModeOptions: Array<{ key: ViewMode; label: string; icon: Component }> = [{ key: 'design', label: '设计', icon: EditPen }, { key: 'preview', label: '预览', icon: View }, { key: 'schema', label: 'Schema', icon: CopyDocument }]

const selectedScope = computed(() => scopes.value.find(item => item.id === selectedScopeId.value) || null)
const draftView = ref(createDraftView('create'))
const masterFields = computed(() => scopeSchema.value?.fields || [])
const selectedView = computed(() => views.value.find(item => item.id === selectedViewId.value) || null)
const activeView = computed(() => selectedView.value || draftView.value)
const activeRole = computed<FormMetadataViewRole>(() => activeView.value.view_role || roleForLegacyType(activeView.value.view_type))
const activeFormMode = computed<FormMetadataFormMode>(() => activeView.value.form_mode || modeForLegacyType(activeView.value.view_type))
const selectedField = computed(() => localFields.value.find(field => field.field_definition_id === selectedFieldId.value) || localFields.value[0] || null)
const sections = computed(() => localLayout.value.sections)
const activeSection = computed(() => sections.value.find(section => section.key === activeSectionKey.value) || sections.value[0] || null)
const supportsSections = computed(() => activeRole.value !== 'list')
const isFormPage = computed(() => activeRole.value === 'create' || activeRole.value === 'edit')
const isReadonlyPage = computed(() => activeRole.value === 'detail' || activeRole.value === 'approval')
const availableFields = computed(() => masterFields.value.filter(field => Boolean(field.enabled) && Boolean(field.form_available) && (activeRole.value !== 'list' || Boolean(field.list_visible)) && !localFields.value.some(item => item.field_definition_id === field.id)))
const steps = computed(() => viewSchema.value?.steps || [])
const displaySteps = computed<Array<{ id?: number; title: string; description?: string | null }>>(() => steps.value.length ? steps.value : [{ title: '基本信息', description: '填写业务对象基础信息' }, { title: '补充信息', description: '填写交付与关联信息' }])
const schemaText = computed(() => JSON.stringify({ schemaVersion: 1, scopeKey: selectedScope.value?.scope_key, view: { key: activeView.value.view_key, name: activeView.value.view_name, role: activeRole.value, formMode: activeFormMode.value, groupKey: activeView.value.view_group_key, layout: localLayout.value }, fields: localFields.value.map(field => ({ fieldDefinitionId: field.field_definition_id, key: field.field_key, label: field.label, sectionKey: field.view_section_key || 'default', sortNo: field.sort_no, columnSpan: field.column_span, columnWidth: field.column_width, fixedPosition: field.fixed_position, filterOperator: field.filter_operator, required: flag(field.required), editable: flag(field.editable), mobileVisible: flag(field.mobile_visible) })) }, null, 2))

const typeLabels: Record<string, string> = { text: '单行文本', textarea: '多行文本', number: '数字', date: '日期', datetime: '日期时间', select: '下拉选择', radio: '单选', checkbox: '多选', boolean: '开关', person: '人员', user: '人员', organization: '组织', attachment: '附件', rich_text: '富文本', json: 'JSON' }
const typeIcons: Record<string, Component> = { text: Document, textarea: EditPen, number: Grid, date: Calendar, datetime: Calendar, select: Check, radio: Check, checkbox: Check, boolean: CircleCheck, person: User, user: User, organization: User, attachment: Paperclip, rich_text: EditPen, json: CopyDocument }

function flag(value: number | boolean | undefined) { return value === true || value === 1 }
function createDefaultLayout(): ViewLayout { return { columns: 24, mobileColumns: 1, labelPosition: 'top', mobileMode: 'card', sections: [{ key: 'default', title: '基本信息', layoutMode: 'full', showTitle: true, collapsed: false, sortNo: 10 }] } }
function createDraftView(role: FormMetadataViewRole): FormMetadataView { const mode: FormMetadataFormMode = role === 'create' || role === 'edit' ? 'single' : 'none'; return { id: 0, scope_id: selectedScopeId.value || 0, view_key: `${role}-${Date.now()}`, view_name: `${viewRoleLabel(role)}配置`, view_type: legacyTypeFor(role, mode), view_role: role, form_mode: mode, view_group_key: selectedScope.value?.scope_key || '', layout_json: createDefaultLayout(), enabled: true } }
function roleForLegacyType(type: FormMetadataViewType): FormMetadataViewRole { return type === 'list' || type === 'detail' || type === 'approval' ? type : 'create' }
function modeForLegacyType(type: FormMetadataViewType): FormMetadataFormMode { return type === 'wizard' ? 'wizard' : type === 'form' ? 'single' : 'none' }
function legacyTypeFor(role: FormMetadataViewRole, mode: FormMetadataFormMode): FormMetadataViewType { return role === 'create' || role === 'edit' ? (mode === 'wizard' ? 'wizard' : 'form') : role }
function normalizeLayout(value: unknown): ViewLayout { let source: Record<string, unknown> = {}; if (typeof value === 'string') { try { source = JSON.parse(value) as Record<string, unknown> } catch { source = {} } } else if (value && typeof value === 'object') source = value as Record<string, unknown>; const raw = Array.isArray(source.sections) ? source.sections : []; const normalized = raw.map((section, index) => { const item = section as Record<string, unknown>; return { key: String(item.key || `section-${index + 1}`), title: String(item.title || `分区 ${index + 1}`), layoutMode: (['left', 'right', 'full'].includes(String(item.layoutMode)) ? String(item.layoutMode) : 'full') as ViewSection['layoutMode'], showTitle: item.showTitle !== false, collapsed: item.collapsed === true, sortNo: Number(item.sortNo || (index + 1) * 10) } }); return { columns: Number(source.columns || 24), mobileColumns: Number(source.mobileColumns || 1), labelPosition: String(source.labelPosition || 'top'), mobileMode: String(source.mobileMode || 'card'), sections: normalized.length ? normalized : createDefaultLayout().sections } }
function viewRoleLabel(role: FormMetadataViewRole) { return pageRoles.find(item => item.key === role)?.label || role }
function viewModeLabel(mode: FormMetadataFormMode) { return mode === 'wizard' ? '分步表单' : mode === 'single' ? '单页表单' : '不适用' }
function typeLabel(type: string) { return typeLabels[type] || type }
function typeIcon(type: string) { return typeIcons[type] || Document }
function viewsForRole(role: FormMetadataViewRole) { return views.value.filter(view => (view.view_role || roleForLegacyType(view.view_type)) === role) }
function fieldsInSection(sectionKey: string) { return localFields.value.filter(field => (field.view_section_key || sections.value[0]?.key || 'default') === sectionKey) }
function inputOptions(field: FormMetadataViewField) { return masterFields.value.find(item => item.id === field.field_definition_id)?.options || [] }

async function loadScopes() { pageError.value = ''; try { const response = await listFormMetadataScopes(); scopes.value = response.data.data; if (!selectedScopeId.value || !scopes.value.some(item => item.id === selectedScopeId.value)) selectedScopeId.value = scopes.value[0]?.id || null } catch (error) { pageError.value = apiErrorMessage(error, '业务对象加载失败，请检查权限和服务状态') } }
async function loadScopeData() { if (!selectedScopeId.value) return; loading.value = true; pageError.value = ''; try { const [schemaResponse, viewResponse] = await Promise.all([getFormMetadataSchema(selectedScopeId.value), listFormMetadataViews(selectedScopeId.value)]); scopeSchema.value = schemaResponse.data.data; views.value = viewResponse.data.data; const preferred = views.value.find(view => (view.view_role || roleForLegacyType(view.view_type)) === 'list') || views.value[0]; if (preferred) { selectedViewId.value = preferred.id; await loadView(preferred.id) } else startNewView('list') } catch (error) { pageError.value = apiErrorMessage(error, '页面集合加载失败，请检查权限和服务状态') } finally { loading.value = false } }
async function loadView(viewId: number) { if (!selectedScopeId.value) return; const response = await getFormMetadataView(selectedScopeId.value, viewId); viewSchema.value = response.data.data; localLayout.value = normalizeLayout(response.data.data.view.layout_json); localFields.value = response.data.data.fields.map(field => ({ ...field, view_section_key: field.view_section_key || localLayout.value.sections[0].key })); syncFieldSections(); activeSectionKey.value = localLayout.value.sections[0]?.key || 'default'; selectedFieldId.value = localFields.value[0]?.field_definition_id || null }
function syncFieldSections() { const known = new Set(sections.value.map(section => section.key)); localFields.value.forEach(field => { const key = field.view_section_key || sections.value[0]?.key || 'default'; field.view_section_key = key; if (!known.has(key)) { localLayout.value.sections.push({ key, title: key, layoutMode: 'full', showTitle: true, collapsed: false, sortNo: (localLayout.value.sections.length + 1) * 10 }); known.add(key) } }); localLayout.value.sections.sort((left, right) => left.sortNo - right.sortNo) }
function resetDraft(role: FormMetadataViewRole = 'create') { selectedViewId.value = null; viewSchema.value = null; draftView.value = createDraftView(role); localLayout.value = createDefaultLayout(); draftView.value.layout_json = localLayout.value; localFields.value = []; activeSectionKey.value = 'default'; selectedFieldId.value = null; previewForm.value = {} }
function startNewView(role: FormMetadataViewRole = 'create') { resetDraft(role); viewMode.value = 'design'; ElMessage.info(`已进入${viewRoleLabel(role)}草稿，请从字段主列表选择字段`) }
function chooseView(view: FormMetadataView) { selectedViewId.value = view.id; void loadView(view.id); viewMode.value = 'design' }
function selectField(field: FormMetadataViewField) { selectedFieldId.value = field.field_definition_id; viewMode.value = 'design' }
function startFieldDrag(event: DragEvent, fieldId: number) { draggingFieldId.value = fieldId; event.dataTransfer?.setData('application/x-form-field-definition', String(fieldId)); if (event.dataTransfer) event.dataTransfer.effectAllowed = 'copy' }
function clearDragState() { draggingFieldId.value = null; dragOverIndex.value = null; dragOverSectionKey.value = null }
function sectionInsertionIndex(sectionKey: string, index: number) { const sectionFields = fieldsInSection(sectionKey); const target = sectionFields[index]; if (target) return localFields.value.indexOf(target); const sectionIndex = sections.value.findIndex(section => section.key === sectionKey); const next = sections.value.slice(sectionIndex + 1).map(section => fieldsInSection(section.key)[0]).find(Boolean); return next ? localFields.value.indexOf(next) : localFields.value.length }
function addField(field: FormMetadataField, index = fieldsInSection(activeSectionKey.value).length, sectionKey = activeSectionKey.value) { const newField: FormMetadataViewField = { view_id: selectedViewId.value || 0, field_definition_id: field.id, view_section_key: sectionKey, sort_no: (localFields.value.length + 1) * 10, visible: true, editable: isFormPage.value, required: false, column_span: field.column_span || 12, column_width: activeRole.value === 'list' ? 140 : null, fixed_position: 'none', filter_operator: activeRole.value === 'list' ? 'contains' : null, mobile_visible: true, enabled: true, field_key: field.field_key, label: field.label, input_type: field.input_type, value_type: field.value_type, form_available: field.form_available, source_type: field.source_type, source_key: field.source_key }; localFields.value.splice(sectionInsertionIndex(sectionKey, index), 0, newField); localFields.value.forEach((item, itemIndex) => { item.sort_no = (itemIndex + 1) * 10 }); selectedFieldId.value = field.id; viewMode.value = 'design' }
function setDragOver(sectionKey: string, index: number) { dragOverSectionKey.value = sectionKey; dragOverIndex.value = index }
function handleCanvasDrop(event: DragEvent, index = fieldsInSection(activeSectionKey.value).length, sectionKey = activeSectionKey.value) { const fieldId = Number(event.dataTransfer?.getData('application/x-form-field-definition') || draggingFieldId.value); const master = masterFields.value.find(field => field.id === fieldId); if (!master) return clearDragState(); const existingIndex = localFields.value.findIndex(field => field.field_definition_id === fieldId); if (existingIndex >= 0) { const [field] = localFields.value.splice(existingIndex, 1); field.view_section_key = sectionKey; localFields.value.splice(sectionInsertionIndex(sectionKey, index), 0, field); localFields.value.forEach((item, itemIndex) => { item.sort_no = (itemIndex + 1) * 10 }); selectedFieldId.value = field.field_definition_id } else addField(master, index, sectionKey); clearDragState() }
async function removeField(field: FormMetadataViewField) { const index = localFields.value.findIndex(item => item.field_definition_id === field.field_definition_id); localFields.value.splice(index, 1); localFields.value.forEach((item, itemIndex) => { item.sort_no = (itemIndex + 1) * 10 }); selectedFieldId.value = localFields.value[Math.max(0, index - 1)]?.field_definition_id || localFields.value[0]?.field_definition_id || null; if (selectedScopeId.value && selectedViewId.value && field.id) { try { await deleteFormMetadataViewField(selectedScopeId.value, selectedViewId.value, field.id); ElMessage.success('字段已从当前页面移除') } catch (error) { ElMessage.error(apiErrorMessage(error, '页面字段移除失败')); await loadView(selectedViewId.value) } } }
function updateSelected(key: keyof FormMetadataViewField, value: unknown) { if (selectedField.value) (selectedField.value as Record<string, unknown>)[key] = value }
function addSection() { const index = sections.value.length + 1; const key = `section-${Date.now()}`; localLayout.value.sections.push({ key, title: `新分区 ${index}`, layoutMode: 'full', showTitle: true, collapsed: false, sortNo: index * 10 }); activeSectionKey.value = key }
function updateActiveSection(key: 'title' | 'layoutMode' | 'showTitle' | 'collapsed', value: unknown) { if (activeSection.value) (activeSection.value as Record<string, unknown>)[key] = value }
function updateDraftMode(mode: FormMetadataFormMode | string) { if (!selectedViewId.value && isFormPage.value && (mode === 'single' || mode === 'wizard')) { draftView.value.form_mode = mode; draftView.value.view_type = legacyTypeFor(activeRole.value, mode) } }
async function removeSection() { if (!activeSection.value || sections.value.length === 1) { ElMessage.warning('至少保留一个视图分区'); return } try { await ElMessageBox.confirm(`删除分区“${activeSection.value.title}”后，字段会移动到相邻分区，确认继续吗？`, '删除视图分区', { type: 'warning' }); const removedKey = activeSection.value.key; const fallback = sections.value.find(section => section.key !== removedKey)!; localFields.value.forEach(field => { if (field.view_section_key === removedKey) field.view_section_key = fallback.key }); localLayout.value.sections = sections.value.filter(section => section.key !== removedKey); activeSectionKey.value = fallback.key } catch (error) { if ((error as { action?: string }).action !== 'cancel') ElMessage.error('分区删除失败') } }
async function saveDraft() { if (!selectedScopeId.value) return; saving.value = true; try { let viewId = selectedViewId.value; const payload = { view_key: activeView.value.view_key, view_name: activeView.value.view_name, view_type: legacyTypeFor(activeRole.value, activeFormMode.value), view_group_key: selectedScope.value?.scope_key, view_role: activeRole.value, form_mode: activeFormMode.value, layout_json: localLayout.value, enabled: 1 }; if (!viewId) { const created = await createFormMetadataView(selectedScopeId.value, payload); viewId = Number(created.data.data.id); selectedViewId.value = viewId; views.value.push(created.data.data) } else await updateFormMetadataView(selectedScopeId.value, viewId, payload); for (const field of localFields.value) { const fieldPayload = { field_definition_id: field.field_definition_id, view_section_key: field.view_section_key || activeSectionKey.value, sort_no: field.sort_no, visible: flag(field.visible) ? 1 : 0, editable: flag(field.editable) ? 1 : 0, required: flag(field.required) ? 1 : 0, column_span: field.column_span, column_width: field.column_width, fixed_position: field.fixed_position || 'none', filter_operator: field.filter_operator, mobile_visible: flag(field.mobile_visible) ? 1 : 0, enabled: flag(field.enabled) ? 1 : 0 }; if (field.id) await updateFormMetadataViewField(selectedScopeId.value, viewId, field.id, fieldPayload); else { const created = await createFormMetadataViewField(selectedScopeId.value, viewId, fieldPayload); field.id = Number(created.data.data.id) } } await loadView(viewId); ElMessage.success('页面草稿已保存，字段均来自业务对象字段主列表') } catch (error) { ElMessage.error(apiErrorMessage(error, '页面保存失败')) } finally { saving.value = false } }
async function publishView() { if (!selectedScopeId.value) return; try { if (!selectedViewId.value) await saveDraft(); if (!selectedViewId.value) return; await ElMessageBox.confirm('发布后该页面配置将成为业务模块可引用的版本，确认发布吗？', '发布页面配置', { type: 'warning', confirmButtonText: '发布' }); const response = await publishFormMetadataView(selectedScopeId.value, selectedViewId.value, `${viewRoleLabel(activeRole.value)} · ${viewModeLabel(activeFormMode.value)} 页面配置`); await loadScopeData(); ElMessage.success(`页面已发布，版本 ${response.data.data.revisionNo}`) } catch (error) { if ((error as { action?: string }).action !== 'cancel') ElMessage.error(apiErrorMessage(error, '页面发布失败')) } }
function updatePreview(key: string, value: unknown) { previewForm.value[key] = value }

watch(selectedScopeId, () => { void loadScopeData() })
onMounted(() => { void loadScopes() })
</script>

<template>
  <section class="object-designer-page">
    <UiPageHeader eyebrow="平台元数据设计器" title="业务对象页面设计器" description="先选择业务对象，再按页面角色配置列表、详情、新建、编辑和审批页面。新建与编辑页内部选择单页表单或分步表单。">
      <template #actions>
        <el-button title="重新加载" :loading="loading" @click="loadScopeData"><el-icon><Refresh /></el-icon>刷新</el-button>
        <el-button type="primary" :loading="saving" :disabled="!selectedScopeId" @click="saveDraft"><el-icon><Check /></el-icon>保存草稿</el-button>
        <el-button type="success" plain :loading="saving" :disabled="!selectedScopeId || !localFields.length" @click="publishView"><el-icon><Upload /></el-icon>发布</el-button>
      </template>
    </UiPageHeader>

    <el-alert v-if="pageError" :title="pageError" type="error" show-icon :closable="false" class="designer-alert" />
    <section class="object-context surface-card">
      <div class="object-context__item object-context__item--object"><span class="context-label">业务对象</span><el-select v-model="selectedScopeId" filterable :loading="loading" placeholder="选择业务对象"><el-option v-for="scope in scopes" :key="scope.id" :label="scope.scope_name" :value="scope.id" /></el-select><small>{{ selectedScope?.scope_key || '未选择' }} · {{ selectedScope?.entity_type || '实体' }}</small></div>
      <div class="object-context__flow"><span class="flow-step is-done">1 <b>业务对象</b></span><span class="flow-line" /><span class="flow-step is-active">2 <b>页面集合</b></span><span class="flow-line" /><span class="flow-step">3 <b>字段布局</b></span></div>
      <div class="object-context__status"><span class="designer-dot" />{{ views.length }} 个页面 · {{ masterFields.length }} 个字段</div>
    </section>

    <section class="page-collection surface-card">
      <header class="section-heading"><div><span class="panel-kicker">PAGE COLLECTION</span><h2>页面集合</h2><p>列表页是业务入口，所有页面共享当前业务对象的字段主列表。</p></div><el-button plain @click="startNewView('create')"><el-icon><Plus /></el-icon>新增页面</el-button></header>
      <div class="page-tree">
        <div v-for="role in pageRoles" :key="role.key" class="page-tree__group">
          <div class="page-tree__group-heading"><span class="page-tree__role-icon"><el-icon><component :is="role.icon" /></el-icon></span><div><strong>{{ role.label }}</strong><small>{{ role.description }}</small></div><em>{{ viewsForRole(role.key).length }}</em><button type="button" :title="`新增${role.label}`" @click="startNewView(role.key)"><el-icon><Plus /></el-icon></button></div>
          <div class="page-tree__items"><button v-for="view in viewsForRole(role.key)" :key="view.id" type="button" class="page-tree__item" :class="{ 'is-active': selectedViewId === view.id }" @click="chooseView(view)"><span>{{ view.view_name }}</span><small>{{ role.key === 'create' || role.key === 'edit' ? viewModeLabel(view.form_mode || modeForLegacyType(view.view_type)) : '只读页面' }}</small></button><div v-if="!viewsForRole(role.key).length" class="page-tree__empty">暂未配置</div></div>
        </div>
      </div>
    </section>

    <section class="page-config surface-card">
      <div class="page-config__identity"><span class="page-role-badge"><el-icon><component :is="pageRoles.find(item => item.key === activeRole)?.icon || Setting" /></el-icon>{{ viewRoleLabel(activeRole) }}</span><div><strong>{{ activeView.view_name }}</strong><small>{{ activeView.view_key }} · {{ activeView.view_group_key || selectedScope?.scope_key }}</small></div></div>
      <div v-if="isFormPage" class="config-control"><span>表单模式</span><el-radio-group :model-value="activeFormMode" :disabled="Boolean(selectedViewId)" @update:model-value="updateDraftMode($event)"><el-radio-button label="single">单页表单</el-radio-button><el-radio-button label="wizard">分步表单</el-radio-button></el-radio-group></div>
      <div v-else class="config-control"><span>页面属性</span><strong>{{ activeRole === 'list' ? '列表列与检索配置' : '只读字段与展示布局' }}</strong></div>
      <div class="config-control"><span>引用字段</span><strong>{{ localFields.length }} / {{ masterFields.length }}</strong></div>
      <div class="page-config__note"><el-icon><InfoFilled /></el-icon><span>字段编码、类型、选项和校验统一维护在“输入项配置”，此处只配置页面级展示属性。</span></div>
    </section>

    <section v-if="viewMode === 'design'" class="designer-workspace">
      <aside class="designer-panel field-registry surface-card"><div class="designer-panel__header"><div><span class="panel-kicker">FIELD REGISTRY</span><h2>字段主列表</h2></div><span class="designer-count">{{ availableFields.length }}</span></div><p class="designer-panel__hint">拖动已登记字段到页面画布。页面不能创建临时字段。</p><div class="component-list"><button v-for="field in availableFields" :key="field.id" type="button" class="component-item" draggable="true" @dragstart="startFieldDrag($event, field.id)" @dragend="clearDragState" @click="addField(field)"><span class="component-item__icon"><el-icon><component :is="typeIcon(field.input_type)" /></el-icon></span><span class="component-item__copy"><strong>{{ field.label }}</strong><small>{{ field.field_key }} · {{ typeLabel(field.input_type) }}</small></span><el-icon class="component-item__drag"><Rank /></el-icon></button></div><el-empty v-if="!availableFields.length" description="字段已全部引用" :image-size="52" /><div class="component-library__note"><el-icon><InfoFilled /></el-icon><span>先在字段主列表维护字段，再进入页面集合配置布局。</span></div></aside>

